  5158  static void*
  5159  md_push_block_bytes(MD_CTX* ctx, int n_bytes)
  5160  {
  5161      void* ptr;
  5162
  5163      if(ctx->n_block_bytes + n_bytes > ctx->alloc_block_bytes) {
  5164          void* new_block_bytes;
  5165
  5166          ctx->alloc_block_bytes = (ctx->alloc_block_bytes > 0
  5167                  ? ctx->alloc_block_bytes + ctx->alloc_block_bytes / 2
  5168                  : 512);
  5169          new_block_bytes = realloc(ctx->block_bytes, ctx->alloc_block_bytes);
  5170          if(new_block_bytes == NULL) {
  5171              MD_LOG("realloc() failed.");
  5172              return NULL;
  5173          }
  5174
  5175          /* Fix the ->current_block after the reallocation. */
  5176          if(ctx->current_block != NULL) {
  5177              OFF off_current_block = (OFF) ((char*) ctx->current_block - (char*) ctx->block_bytes);
  5178              ctx->current_block = (MD_BLOCK*) ((char*) new_block_bytes + off_current_block);
  5179          }
  5180
  5181          ctx->block_bytes = new_block_bytes;
  5182      }
  5183
  5184      ptr = (char*)ctx->block_bytes + ctx->n_block_bytes;
  5185      ctx->n_block_bytes += n_bytes;
  5186      return ptr;
  5187  }
