  5298      /* Check whether there is a reference definition. (We do this here instead
  5299       * of in md_analyze_line() because reference definition can take multiple
  5300       * lines.) */
  5301      if(ctx->current_block->type == MD_BLOCK_P  ||
  5302         (ctx->current_block->type == MD_BLOCK_H  &&  (ctx->current_block->flags & MD_BLOCK_SETEXT_HEADER)))
  5303      {
  5304          MD_LINE* lines = (MD_LINE*) (ctx->current_block + 1);
  5305          if(lines[0].beg < ctx->size  &&  CH(lines[0].beg) == _T('[')) {
  5306              MD_CHECK(md_consume_link_reference_definitions(ctx));
  5307              if(ctx->current_block == NULL)
  5308                  return ret;
  5309          }
  5310      }
  5311
  5312      if(ctx->current_block->type == MD_BLOCK_H  &&  (ctx->current_block->flags & MD_BLOCK_SETEXT_HEADER)) {
  5313          MD_SIZE n_lines = ctx->current_block->n_lines;
  5314
  5315          if(n_lines > 1) {
  5316              /* Get rid of the underline. */
  5317              ctx->current_block->n_lines--;
  5318              ctx->n_block_bytes -= sizeof(MD_LINE);
  5319          } else {
  5320              /* Only the underline has left after eating the ref. defs.
  5321               * Keep the line as beginning of a new ordinary paragraph. */
  5322              ctx->current_block->type = MD_BLOCK_P;
  5323              return 0;
  5324          }
  5325      }
  5326
  5327      /* Mark we are not building any block anymore. */
  5328      ctx->current_block = NULL;
